Func<Orc.Game.Damage.DamageApplyView, Context, CancellationToken, Task> HandleAsync = (view, ctx, ct) =>
{
    if (view.Host is not Orc.Cards.Card self)
    {
        return Task.CompletedTask;
    }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(self);
    if (runtime is null)
    {
        return Task.CompletedTask;
    }

    if (runtime.Judge(Orc.Game.Judicators.JudicatorNames.UnitAdjacent, self, view.Target)
        && runtime.Judge(Orc.Game.Judicators.JudicatorNames.UnitTypeMatch, view.Target, "infantry")
        && runtime.Judge(Orc.Game.Judicators.JudicatorNames.UnitSide, self, view.Target))
    {
        view.Amount = System.Math.Max(0, view.Amount - 1);
    }

    return Task.CompletedTask;
};
